with filtered as (select *, date_format(event_time, 'yyyy-MM') as event_time_label from web_events where event_time > date '2023-12-11') select id, session_id, event_type, page, event_time, duration_sec, event_time_label, avg(duration_sec) over (partition by page order by duration_sec, id rows between 2 preceding and 1 preceding) as duration_sec_avg_2_prior, count(duration_sec) over (partition by event_type, session_id order by cast(event_time as bigint) range between 604800 preceding and current row) as duration_sec_count_7d from filtered;
